phase("Research");
const first = agent("Researcher A").ask("E2E_DWI_TASK_A Study the first source and give a one-line finding.");
const second = agent("Researcher B").ask("E2E_DWI_TASK_B Study the second source and give a one-line finding.");
// Both studies run in parallel and the digest needs both findings: this is the only join.
const [a, b] = await Promise.all([first, second]);
phase("Digest");
const summary = await agent("Digester").ask(`E2E_DWI_TASK_C Merge the two findings: ${a} / ${b}`);
return { summary, parts: [a, b] };
